import {useCallback, useEffect, useRef, useState} from 'react'
import {statusLabel} from './taskApi'

type Locale = 'zh' | 'en'
type Row = Record<string, any>
type Props = {locale: Locale; onBack: () => void}
type CourseDraft = {language: Locale; title: string; description: string; objectives: Row[]; selected: string[]; blueprint: Row | null; knowledge_cards: Row[]; micro_practices: Row[]; saved_at?: string}
type MicroAnswer = {response_text: string; self_reflection: string; hint_used: boolean; skipReflection: boolean; request_id: string}
type MicroLoadError = {title: string; message: string}
type CourseAgentMessage = {role: 'assistant' | 'user'; text: string}
class LearningApiError extends Error {
  constructor(readonly status: number, readonly detail: unknown, message: string) {super(message)}
}
const draftKey = (locale: Locale) => `theraskill-learning-course-draft:v2:${locale}`
const blankDraft = (language: Locale): CourseDraft => ({language, title: '', description: '', objectives: [], selected: [], blueprint: null, knowledge_cards: [], micro_practices: []})
function readDraft(locale: Locale): CourseDraft {
  try {const value = JSON.parse(localStorage.getItem(draftKey(locale)) || 'null'); return value?.language === locale && Array.isArray(value.objectives) ? {...blankDraft(locale), ...value} : blankDraft(locale)} catch {return blankDraft(locale)}
}
const newId = () => typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : `${Date.now()}_${Math.random().toString(16).slice(2)}`
const pendingJob = (job: Row) => ['queued', 'pending', 'running'].includes(job?.status)
const asText = (value: any) => typeof value === 'string' ? value : value?.message || value?.detail || (value ? JSON.stringify(value) : '')
const agentDraftKey = (locale: Locale) => `theraskill-learning-course-agent:v1:${locale}`
const initialAgentMessage = (locale: Locale): CourseAgentMessage => ({role: 'assistant', text: locale === 'zh' ? '我可以和你一起设计课程。先告诉我：学员要练会什么，以及准备做几个案例。我会先整理计划，等你确认后再检索知识和生成内容。' : 'I can design the course with you. Tell me what learners should practise and how many cases you want. I will show a plan and wait for confirmation before retrieving knowledge or generating content.'})

export default function LearningStudio({locale, onBack}: Props) {
  const t = (zh: string, en: string) => locale === 'zh' ? zh : en
  const [role, setRole] = useState<'instructor' | 'human_therapist'>(() => sessionStorage.getItem('theraskill-learning-role') === 'human_therapist' ? 'human_therapist' : 'instructor')
  const [assignee, setAssignee] = useState(() => sessionStorage.getItem('theraskill-learning-label') || '')
  const [tab, setTab] = useState<'design' | 'practice' | 'progress'>(role === 'instructor' ? 'design' : 'practice')
  const [draft, setDraft] = useState<CourseDraft>(() => readDraft(locale))
  const [report, setReport] = useState<Row | null>(null)
  const [courses, setCourses] = useState<Row[]>([])
  const [scenarios, setScenarios] = useState<Row[]>([])
  const [courseId, setCourseId] = useState(() => new URLSearchParams(location.search).get('course_id') || '')
  const [assignmentTitle, setAssignmentTitle] = useState('')
  const [starterTemplate, setStarterTemplate] = useState('foundation_first_session')
  const [starterCount, setStarterCount] = useState(() => readDraft(locale).blueprint?.scenario_constraints?.count || 3)
  const [difficultyBand, setDifficultyBand] = useState(() => readDraft(locale).blueprint?.scenario_constraints?.difficulty_band || 'low')
  const [riskBand, setRiskBand] = useState(() => readDraft(locale).blueprint?.scenario_constraints?.risk_band || 'low')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [agentInput, setAgentInput] = useState('')
  const [agentMessages, setAgentMessages] = useState<CourseAgentMessage[]>(() => {
    try { const value = JSON.parse(sessionStorage.getItem(agentDraftKey(locale)) || 'null'); return Array.isArray(value?.messages) ? value.messages : [initialAgentMessage(locale)] } catch { return [initialAgentMessage(locale)] }
  })
  const [agentPlan, setAgentPlan] = useState<Row>(() => {
    try { return JSON.parse(sessionStorage.getItem(agentDraftKey(locale)) || 'null')?.plan || {} } catch { return {} }
  })
  const [agentAction, setAgentAction] = useState('')
  const [agentBusy, setAgentBusy] = useState(false)
  const [advancedOpen, setAdvancedOpen] = useState(false)
  const [micro, setMicro] = useState<Record<string, Row>>({})
  const [microErrors, setMicroErrors] = useState<Record<string, MicroLoadError>>({})
  const [answers, setAnswers] = useState<Record<string, MicroAnswer>>({})
  const [reflections, setReflections] = useState<Record<string, string>>({})
  const [reflectionUnlocked, setReflectionUnlocked] = useState<Record<string, boolean>>({})
  const [links, setLinks] = useState<Record<string, string>>({})
  const [jobs, setJobs] = useState<Record<string, Row>>({})
  const [openReview, setOpenReview] = useState('')
  const [reviewer, setReviewer] = useState('')
  const [comment, setComment] = useState('')
  const [ratings, setRatings] = useState<Record<string, number>>({})
  const [performanceLevel, setPerformanceLevel] = useState('guided')
  const [transferContext, setTransferContext] = useState('')
  const [reviewEvidence, setReviewEvidence] = useState<string[]>([])
  const [safetyIssue, setSafetyIssue] = useState(false)
  const [behaviorObservations, setBehaviorObservations] = useState<Record<string, Row[]>>({})
  const [microScore, setMicroScore] = useState('')
  const mounted = useRef(true)
  const loadVersion = useRef(0)
  const microScope = useRef('')
  const call = useCallback(async (path: string, body?: any) => {
    const response = await fetch('/api/simulation' + path, {method: body === undefined ? 'GET' : 'POST', headers: {'Content-Type': 'application/json', 'X-Simulation-Role': role, 'X-Simulation-User': 'local-user'}, body: body === undefined ? undefined : JSON.stringify(body)})
    const result = response.status === 204 ? {} : await response.json().catch(() => null)
    if (!response.ok) {
      const detail = result?.detail
      const message = Array.isArray(detail) ? detail.map(item => `${(item.loc || []).join('.')}: ${item.msg || ''}`).join('; ') : typeof detail === 'string' ? detail : response.statusText || `HTTP ${response.status}`
      throw new LearningApiError(response.status, detail, message)
    }
    if (result === null) throw new Error('Invalid JSON response')
    return result
  }, [role])
  const act = async (fn: () => Promise<any>) => {setBusy(true); setError(''); setNotice(''); try {await fn()} catch (e) {if (mounted.current) setError(e instanceof Error ? e.message : String(e))} finally {if (mounted.current) setBusy(false)}}
  const resetReview = () => {setOpenReview(''); setReviewer(''); setComment(''); setRatings({}); setPerformanceLevel('guided'); setTransferContext(''); setReviewEvidence([]); setSafetyIssue(false); setBehaviorObservations({}); setMicroScore('')}
  const chooseReview = (key: string) => {const next = openReview === key ? '' : key; resetReview(); setOpenReview(next)}
  const microLoadMessage = (reason: unknown) => {
    if (reason instanceof LearningApiError && reason.status === 404 && reason.detail === 'Not Found') return t('当前运行的服务尚未提供微练习接口。更新代码后请重启 TheraSkillAgent 服务，再重试加载。', 'The running service does not provide the micro-practice API. After updating the code, restart TheraSkillAgent, then retry loading.')
    const detail = reason instanceof Error ? reason.message : String(reason)
    const status = reason instanceof LearningApiError ? ` (HTTP ${reason.status})` : ''
    return t('微练习加载失败：', 'Micro-practices could not load: ') + detail + status
  }
  const recoveredJobs = (value: Row): Record<string, Row> => {
    const recovered: Record<string, Row> = {}
    for (const submission of value.submissions || []) if (submission.latest_judge_job) recovered['submission:' + submission.submission_id] = submission.latest_judge_job
    for (const [attemptId, history] of Object.entries(value.attempt_judge_jobs || {})) {const rows = history as Row[]; if (rows.length) recovered['attempt:' + attemptId] = rows[rows.length - 1]}
    return recovered
  }
  const retryMicro = (assignmentId: string) => act(async () => {
    const version = loadVersion.current
    try {
      const value = await call('/assignments/' + encodeURIComponent(assignmentId) + '/micro-practices')
      if (!mounted.current || version !== loadVersion.current) return
      setMicro(previous => ({...previous, [assignmentId]: value}))
      setJobs(previous => ({...previous, ...recoveredJobs(value)}))
      setMicroErrors(previous => {const next = {...previous}; delete next[assignmentId]; return next})
    } catch (reason) {
      if (mounted.current && version === loadVersion.current) setMicroErrors(previous => ({...previous, [assignmentId]: {...previous[assignmentId], message: microLoadMessage(reason)}}))
    }
  })
  const refresh = async () => {
    const version = ++loadVersion.current
    const scope = JSON.stringify([role, locale, assignee.trim()])
    const cachedMicro = microScope.current === scope ? micro : {}
    if (microScope.current !== scope) {setMicro({}); setMicroErrors({}); setJobs({})}
    const [r, s, c] = await Promise.all([call('/learning/report' + (assignee.trim() ? '?assignee=' + encodeURIComponent(assignee.trim()) : '')), call('/scenarios?language=' + locale), role === 'instructor' ? call('/courses') : Promise.resolve(null)])
    if (!mounted.current || version !== loadVersion.current) return
    setReport(r); setScenarios((s.scenarios || []).filter((item: Row) => !item.generated || item.review_status === 'approved')); setCourses(c?.courses || r.assignments.map((item: Row) => item.course).filter(Boolean)); if (courseId && !assignmentTitle) setAssignmentTitle((c?.courses || []).find((item: Row) => item.course_id === courseId)?.title || '')
    const assignments: Row[] = r.assignments || []
    const rows = await Promise.allSettled(assignments.map(async item => [item.assignment.assignment_id, await call('/assignments/' + encodeURIComponent(item.assignment.assignment_id) + '/micro-practices')] as const))
    if (!mounted.current || version !== loadVersion.current) return
    const nextMicro: Record<string, Row> = {}; const recovered: Record<string, Row> = {}; const failures: Record<string, MicroLoadError> = {}
    rows.forEach((result, index) => {
      const assignment = assignments[index].assignment; const id = assignment.assignment_id
      if (result.status === 'fulfilled') nextMicro[id] = result.value[1]
      else {if (cachedMicro[id]) nextMicro[id] = cachedMicro[id]; failures[id] = {title: assignment.title || id, message: microLoadMessage(result.reason)}}
      if (nextMicro[id]) Object.assign(recovered, recoveredJobs(nextMicro[id]))
    })
    for (const assignment of r.assignments || []) for (const attempt of assignment.attempts || []) if (attempt.latest_judge_job) recovered['attempt:' + attempt.id] = attempt.latest_judge_job
    const retainJobKeys = assignments.filter(item => failures[item.assignment.assignment_id]).flatMap(item => [
      ...(nextMicro[item.assignment.assignment_id]?.submissions || []).map((submission: Row) => 'submission:' + submission.submission_id),
      ...(item.attempts || []).map((attempt: Row) => 'attempt:' + attempt.id),
    ])
    microScope.current = scope; setMicro(nextMicro)
    setJobs(previous => {const next = {...recovered}; for (const key of retainJobKeys) if (previous[key]) next[key] = previous[key]; return next})
    setMicroErrors(failures)
  }
  useEffect(() => {mounted.current = true; return () => {mounted.current = false; loadVersion.current += 1}}, [])
  useEffect(() => {const saved = readDraft(locale); setDraft(saved); setStarterCount(saved.blueprint?.scenario_constraints?.count || 3); setDifficultyBand(saved.blueprint?.scenario_constraints?.difficulty_band || 'low'); setRiskBand(saved.blueprint?.scenario_constraints?.risk_band || 'low')}, [locale])
  useEffect(() => {if (draft.language === locale) try {localStorage.setItem(draftKey(locale), JSON.stringify({...draft, saved_at: new Date().toISOString()}))} catch {setError(t('浏览器无法保存课程草稿，请在离开前保存课程。', 'The browser cannot save this draft. Save the course before leaving.'))}}, [draft, locale])
  useEffect(() => {
    resetReview(); setJobs({}); setAnswers({}); setReflections({}); setReflectionUnlocked({}); setReport(null); setMicro({}); setMicroErrors({}); setTab(role === 'instructor' ? 'design' : 'practice')
    if (role === 'instructor' || assignee.trim()) void act(refresh)
    return () => {loadVersion.current += 1}
  }, [role, locale])
  useEffect(() => {sessionStorage.setItem('theraskill-learning-role', role); sessionStorage.setItem('theraskill-learning-label', assignee)}, [role, assignee])
  useEffect(() => {
    const active = Object.entries(jobs).filter(([, job]) => pendingJob(job))
    if (!active.length) return
    let alive = true
    const timer = window.setTimeout(async () => {
      const results = await Promise.allSettled(active.map(async ([key, job]) => [key, await call('/learning/judge-jobs/' + encodeURIComponent(job.job_id))] as const))
      if (!alive) return
      for (const result of results) if (result.status === 'fulfilled') {const [key, value] = result.value; setJobs(previous => ({...previous, [key]: value}))}
      if (results.some(result => result.status === 'rejected')) setError(t('反馈任务状态暂时无法读取，可点击重新加载进展。', 'Feedback status could not be read. Reload progress to reconnect.'))
    }, 1800)
    return () => {alive = false; clearTimeout(timer)}
  }, [jobs, call])
  useEffect(() => {setDraft(current => {if (!current.blueprint || current.language !== locale) return current; const constraints = current.blueprint.scenario_constraints || {}; if (constraints.count === starterCount && constraints.difficulty_band === difficultyBand && constraints.risk_band === riskBand) return current; return {...current, blueprint: {...current.blueprint, scenario_constraints: {...constraints, count: starterCount, difficulty_band: difficultyBand, risk_band: riskBand}}}})}, [starterCount, difficultyBand, riskBand, locale])
  const patchDraft = (patch: Partial<CourseDraft>) => setDraft(current => ({...current, ...patch}))
  const patchGoal = (index: number, patch: Row) => setDraft(current => {const old = current.objectives[index]; const behaviors = patch.observable_behaviors as string[] | undefined; return {...current, objectives: current.objectives.map((item, i) => i === index ? {...item, ...patch} : item), micro_practices: behaviors ? current.micro_practices.map(exercise => {if (exercise.competency_id !== old.id) return exercise; const position = (old.observable_behaviors || []).indexOf(exercise.target_behavior); return {...exercise, target_behavior: (position >= 0 ? behaviors[position] : '')?.trim() || behaviors.find(value => value.trim())?.trim() || ''}}) : current.micro_practices}})
  const patchUnit = (kind: 'knowledge_cards' | 'micro_practices', index: number, patch: Row) => setDraft(current => ({...current, [kind]: current[kind].map((item, i) => i === index ? {...item, ...patch} : item)}))
  const coursePayload = () => ({title: draft.title.trim(), description: draft.description.trim(), scenario_ids: draft.selected, skill_tags: draft.objectives.map(item => item.id), learning_objectives: draft.objectives.map(item => ({...item, description: item.description.trim(), observable_behaviors: (item.observable_behaviors || []).map((value: string) => value.trim()).filter(Boolean)})), template_id: draft.blueprint?.template_id, competency_ids: draft.objectives.map(item => item.id), scaffolding: draft.blueprint?.scaffolding || [], learning_units: {knowledge_cards: draft.knowledge_cards, micro_practices: draft.micro_practices}, knowledge_references: draft.blueprint?.knowledge_references || [], design_retrieval: draft.blueprint?.retrieval || {}, require_instructor_review: true})
  const validDraft = !!draft.title.trim() && draft.objectives.length > 0 && draft.objectives.length <= 12 && draft.objectives.every(item => {const values = (item.observable_behaviors || []).map((value: string) => value.trim()).filter(Boolean); return item.description?.trim() && values.length > 0 && values.length <= 8 && new Set(values).size === values.length})
  const buildBlueprint = () => act(async () => {
    const result = await call('/courses/blueprint', {template_id: starterTemplate, scenario_count: starterCount, difficulty_band: difficultyBand, risk_band: riskBand, language: locale})
    setDraft({language: locale, title: result.title, description: result.description, objectives: result.objectives || [], selected: [], blueprint: result, knowledge_cards: result.knowledge_cards || [], micro_practices: result.micro_practices || []})
    setAdvancedOpen(true)
    setNotice(t('课程草案已生成。下面的目标、行为、知识卡和微练习都可以修改。', 'Your starter is ready. Edit its objectives, behaviours, cards, and exercises below.'))
  })
  const buildBlueprintFromAgent = () => act(async () => {
    const plan = agentPlan
    const result = await call('/courses/blueprint', {
      template_id: plan.template_id || starterTemplate,
      title: plan.title || plan.description,
      scenario_count: Number(plan.scenario_count || starterCount),
      difficulty_band: plan.difficulty_band || difficultyBand,
      risk_band: plan.risk_band || riskBand,
      language: locale,
    })
    setStarterTemplate(plan.template_id || starterTemplate)
    setStarterCount(Number(plan.scenario_count || starterCount))
    setDifficultyBand(plan.difficulty_band || difficultyBand)
    setRiskBand(plan.risk_band || riskBand)
    setDraft({language: locale, title: result.title, description: result.description, objectives: result.objectives || [], selected: [], blueprint: result, knowledge_cards: result.knowledge_cards || [], micro_practices: result.micro_practices || []})
    setAdvancedOpen(true)
    setAgentAction('')
    setAgentMessages(current => [...current, {role: 'assistant', text: t('课程草案已经生成。知识依据、教学目标、知识卡和微练习都在草稿中；你可以让我修改，也可以展开高级编辑。', 'The course draft is ready. Its references, objectives, knowledge cards and micro-practices are visible in the draft. Ask me to revise it or open Advanced editing.')}])
    setNotice(t('Agent 已生成课程草案；尚未生成病例，也未保存为正式课程。', 'The Agent created a course draft. No cases were generated and nothing was saved as a formal course yet.'))
  })
  const sendCourseAgent = async () => {
    const message = agentInput.trim()
    if (!message || agentBusy) return
    setAgentBusy(true); setError('')
    const userMessage: CourseAgentMessage = {role: 'user', text: message}
    try {
      const result = await call('/courses/agent-turn', {
        message,
        language: locale,
        draft: {title: draft.title, description: draft.description, scenario_count: starterCount, template_id: starterTemplate, difficulty_band: difficultyBand, risk_band: riskBand, ...agentPlan},
      })
      const nextPlan = result.draft || {}
      setAgentPlan(nextPlan)
      if (nextPlan.title) patchDraft({title: nextPlan.title})
      if (nextPlan.description) patchDraft({description: nextPlan.description})
      if (nextPlan.template_id) setStarterTemplate(nextPlan.template_id)
      if (nextPlan.scenario_count) setStarterCount(Number(nextPlan.scenario_count))
      if (nextPlan.difficulty_band) setDifficultyBand(nextPlan.difficulty_band)
      if (nextPlan.risk_band) setRiskBand(nextPlan.risk_band)
      setAgentMessages(current => [...current, userMessage, {role: 'assistant', text: result.reply}])
      setAgentAction(result.suggested_action || '')
      setAgentInput('')
    } catch (reason) {
      setAgentMessages(current => [...current, userMessage, {role: 'assistant', text: reason instanceof Error ? reason.message : String(reason)}])
    } finally { setAgentBusy(false) }
  }
  useEffect(() => { try { sessionStorage.setItem(agentDraftKey(locale), JSON.stringify({messages: agentMessages, plan: agentPlan})) } catch {} }, [agentMessages, agentPlan, locale])
  const saveCourse = () => act(async () => {const saved = await call('/courses', coursePayload()); setCourseId(saved.course_id); setAssignmentTitle(saved.title); await refresh(); setNotice(t('课程已保存，可分配给学员。', 'Course saved. You can now assign it to a learner.'))})
  const generateCases = () => act(async () => {
    const payload = coursePayload(); const base = draft.blueprint?.generation_payload || {}; const goals = draft.objectives.map(item => item.description).join('; ')
    const constraints = draft.objectives.map(item => `${item.description}: ${(item.observable_behaviors || []).join('; ')}`).join('\n')
    if (goals.length > 1200 || constraints.length > 2000) throw new Error(t('课程目标较长。请缩短目标与行为说明后生成病例；完整知识卡仍会保存在课程中。', 'Please shorten objectives and behaviours before generating cases. Full knowledge cards remain in the course.'))
    localStorage.setItem(draftKey(locale), JSON.stringify({...draft, saved_at: new Date().toISOString()}))
    const job = await call('/scenarios/generate-batch/jobs', {...base, course_title: payload.title, course_description: payload.description, brief: goals.length >= 8 ? goals : `${payload.title}: ${goals}`, constraints, count: starterCount, scenario_family: base.scenario_family || 'supportive_exploration', difficulty_band: difficultyBand, risk_band: riskBand, language: locale, skill_tags: payload.skill_tags, template_id: payload.template_id, competency_ids: payload.competency_ids, scaffolding: payload.scaffolding, learning_objectives: payload.learning_objectives, learning_units: payload.learning_units, knowledge_references: payload.knowledge_references, design_retrieval: payload.design_retrieval})
    location.href = '/theraskill/simulation/?batch_job=' + encodeURIComponent(job.job_id)
  })
  const startPractice = (assignment: Row, scenarioId: string) => act(async () => {
    const key = 'learning-start:' + assignment.assignment_id + ':' + scenarioId; let requestId = sessionStorage.getItem(key)
    if (!requestId) {requestId = newId(); sessionStorage.setItem(key, requestId)}
    const attempt = await call('/assignments/' + assignment.assignment_id + '/practice', {scenario_id: scenarioId, language: locale, request_id: requestId}); sessionStorage.removeItem(key); location.href = '/theraskill/simulation/?session_id=' + encodeURIComponent(attempt.session_id)
  })
  const saveReflection = (attempt: Row) => act(async () => {await call('/learning/attempts/' + attempt.id + '/reflection', {reflection: reflections[attempt.id] ?? attempt.self_reflection ?? ''}); setReflectionUnlocked(current => ({...current, [attempt.id]: true})); await refresh()})
  const updateBehavior = (objectiveId: string, behavior: string, patch: Row) => setBehaviorObservations(current => {const rows = [...(current[objectiveId] || [])]; const index = rows.findIndex(item => item.behavior === behavior); const next = {behavior, ...(rows[index] || {}), ...patch}; if (index < 0) rows.push(next); else rows[index] = next; return {...current, [objectiveId]: rows}})
  const submitReview = (attempt: Row, decision: string) => act(async () => {await call('/learning/attempts/' + attempt.id + '/review', {decision, ratings, comment, reviewer, performance_level: performanceLevel, transfer_context: transferContext, evidence_unit_ids: reviewEvidence, safety_issue: safetyIssue, behavior_observations: behaviorObservations}); resetReview(); await refresh()})
  const answerFor = (key: string): MicroAnswer => answers[key] || {response_text: '', self_reflection: '', hint_used: false, skipReflection: false, request_id: ''}
  const setAnswer = (key: string, patch: Partial<MicroAnswer>) => setAnswers(current => ({...current, [key]: {...answerFor(key), ...patch}}))
  const submitMicro = (assignmentId: string, exercise: Row) => act(async () => {
    const key = assignmentId + ':' + exercise.practice_id; const value = answerFor(key); const requestId = value.request_id || newId(); setAnswer(key, {request_id: requestId})
    await call('/assignments/' + assignmentId + '/micro-practices', {practice_id: exercise.practice_id, response_text: value.response_text, self_reflection: value.self_reflection, hint_used: value.hint_used, request_id: requestId, language: locale})
    setAnswers(current => {const next = {...current}; delete next[key]; return next}); await refresh(); setNotice(t('回应已保存。你可以获取有引文依据的练习反馈。', 'Response saved. You can now request feedback with source citations.'))
  })
  const runJudge = (kind: 'attempt' | 'submission', id: string) => act(async () => {const job = await call(`/learning/${kind === 'attempt' ? 'attempts' : 'submissions'}/${id}/judge`, {language: locale}); setJobs(current => ({...current, [kind + ':' + id]: job}))})
  const retryJudge = (key: string, job: Row) => act(async () => {const retried = await call('/learning/judge-jobs/' + job.job_id + '/retry', {}); setJobs(current => ({...current, [key]: retried}))})
  const label = (value: string) => ({observed: t('已观察到', 'Observed'), not_observed: t('本次未观察到', 'Not observed'), not_applicable: t('本次不适用', 'Not applicable'), approved: t('教师已认可', 'Approved by instructor'), needs_practice: t('继续练习', 'More practice suggested'), rejected: t('需要修改', 'Revision needed')} as Record<string, string>)[value] || statusLabel(value, locale)
  const sourceList = (references: Row[]) => <div className="learning-references">{references.map((item, index) => <blockquote key={`${item.unit_id}-${index}`}><strong>{item.label || item.unit_id}</strong><p>{item.quote || item.text}</p><small>{item.unit_id}</small></blockquote>)}</div>
  const citations = (finding: Row) => <>{(finding.transcript_evidence || []).map((quote: Row, index: number) => <blockquote key={'t' + index}><span>{t('对话依据', 'Dialogue evidence')} · {quote.turn_id}</span><p>{quote.quote}</p></blockquote>)}{(finding.knowledge_evidence || []).map((quote: Row, index: number) => <blockquote key={'k' + index}><span>{t('知识依据', 'Knowledge evidence')} · {quote.unit_id}</span><p>{quote.quote}</p></blockquote>)}</>
  const knowledgeNote = (finding: Row) => finding.knowledge_grounding === 'rubric_only' ? <p className="hint-note">{t('此项按课程标准观察，未引用适用知识。', 'This finding uses the course rubric; no applicable knowledge was cited.')} {finding.knowledge_note || ''}</p> : finding.knowledge_note ? <p className="hint-note">{finding.knowledge_note}</p> : null
  const judgeView = (key: string, objectives: Row[] = []) => {
    const job = jobs[key]; if (!job) return null
    const result = job.result || {}; const stale = job.source_current === false
    return <section className="learning-feedback" aria-live="polite"><div className="learning-heading"><h4>{t('AI 练习反馈', 'AI practice feedback')}</h4><span className="job-status">{statusLabel(job.status, locale)}</span></div><p>{t('用于发现可以改进的行为，教师评价独立保留。', 'Use this feedback to identify practice targets. Instructor reviews are recorded separately.')}</p>{pendingJob(job) && <p>{t('正在核对行为和引文，刷新页面后仍可继续查看。', 'Checking behaviours and citations. You can return after refreshing.')}{job.progress?.stage && ' · ' + statusLabel(job.progress.stage, locale)}</p>}{job.error && <p role="alert">{asText(job.error)}</p>}{stale && <p className="warning-note">{t('练习、课程或模型／知识配置已变化。这份反馈属于旧版本，请重新评估。', 'Practice, course, model or knowledge settings have changed. Request a new assessment for the current version.')}</p>}{(job.retry_allowed === true || (job.retry_allowed === undefined && ['failed', 'partial', 'interrupted'].includes(job.status))) && <button disabled={busy} onClick={() => void retryJudge(key, job)}>{t('重试未完成的反馈', 'Retry feedback')}</button>}{result.objectives?.length > 0 && <><p className="hint-note">{result.evidence_mode === 'knowledge_grounded' ? t('反馈引用了实际对话与检索知识。', 'Feedback cites actual dialogue and retrieved knowledge.') : t('本次按课程行为标准反馈，未引用适用知识。', 'Feedback uses the course rubric; no applicable knowledge sources were cited.')}</p>{result.objectives.map((objective: Row) => <article className="learning-finding" key={objective.objective_id}><strong>{objectives.find(item => item.id === objective.objective_id)?.description || objective.objective_id}</strong><p>{label(objective.observation)}{objective.rating != null && ` · ${objective.rating}/5`}</p><p>{objective.rationale}</p>{knowledgeNote(objective)}{citations(objective)}{(objective.behaviors || []).map((behavior: Row, index: number) => <div className="learning-behavior-result" key={behavior.behavior_id || index}><strong>{behavior.description}</strong><p>{label(behavior.observation)} · {behavior.rationale}</p>{knowledgeNote(behavior)}{citations(behavior)}</div>)}{objective.next_practice?.length > 0 && <ul>{objective.next_practice.map((text: string, index: number) => <li key={index}>{text}</li>)}</ul>}</article>)}{result.next_practice?.length > 0 && <><h4>{t('下一次试试', 'Try next time')}</h4><ul>{result.next_practice.map((text: string, index: number) => <li key={index}>{text}</li>)}</ul></>}</>}{result.provenance && <details><summary>{t('评阅记录', 'Assessment record')}</summary><dl className="learning-assessment-meta"><div><dt>{t('模型', 'Model')}</dt><dd>{result.provenance.model || '—'}</dd></div><div><dt>{t('评阅模板', 'Assessment template')}</dt><dd>{result.provenance.prompt_id || '—'}</dd></div><div><dt>{t('知识索引', 'Knowledge index')}</dt><dd>{result.retrieval?.index_id || '—'}</dd></div><div><dt>{t('知识版本', 'Knowledge release')}</dt><dd>{result.retrieval?.release_id || '—'}</dd></div><div><dt>{t('已完成阶段', 'Completed stages')}</dt><dd>{asText(result.provenance.stages)}</dd></div><div><dt>{t('引文核对', 'Citation check')}</dt><dd>{result.provenance.citation_validation === 'exact_source_and_quote' ? t('已核对来源编号与原文摘录', 'Source IDs and exact excerpts checked') : t('未提供验证记录', 'No verification record provided')}</dd></div></dl></details>}</section>
  }
  const humanFeedback = (review: Row) => <div className="learning-human-feedback"><strong>{label(review.decision)} · {review.reviewer}</strong><p>{review.comment}</p>{review.score != null && <p>{t('教师评分', 'Instructor rating')}: {review.score}/5</p>}{Object.entries(review.behavior_observations || {}).map(([objective, observations]) => <ul key={objective}>{(observations as Row[]).map((item, index) => <li key={index}><strong>{item.behavior}</strong> · {label(item.status)}{item.score != null && ` · ${item.score}/5`}{item.note && <p>{item.note}</p>}</li>)}</ul>)}{review.safety_issue && <p className="warning-note">{t('教师标记了需要督导处理的问题，请先联系教师。', 'The instructor marked an issue requiring supervision. Contact your instructor before proceeding.')}</p>}</div>
  const nextStep = (row: Row) => {
    const step = row.next_step || {}; const type = step.kind || step.action || step.type || step.code || ''
    const texts: Record<string, string> = {supervision: t('先与教师讨论标记的问题，再继续练习。', 'Discuss the flagged issue with your instructor before continuing.'), review: t('先记录反思，再查看反馈和教师建议。', 'Record your reflection, then review feedback and instructor suggestions.'), spaced_transfer: t('稍后换一个情境再次练习，观察不同情境中的应用。', 'Return later with a different case to observe application across contexts.'), start_practice: t('先读知识卡，再开始第一个案例。', 'Read the knowledge cards, then start your first case.'), practice: t('选择下面的案例，继续练习目标行为。', 'Choose a case below and practise the target behaviours.'), instructor_review: t('练习已完成，等待教师反馈；可以先记录自己的反思。', 'Practice is complete. Record your reflection while awaiting instructor feedback.'), await_review: t('等待教师复核，并回看自己的对话。', 'Await instructor review and revisit your dialogue.'), retry: t('根据上次反馈重新练习。', 'Practise again using your previous feedback.'), transfer: t('和教师一起选择不同情境，观察能否迁移。', 'Choose a different context with your instructor to observe transfer.'), safety_review: t('先与教师讨论标记的问题，再继续练习。', 'Discuss the flagged issue with your instructor before continuing.')}
    return texts[type] || (row.status === 'completed' ? t('本课程案例已完成。回看反馈，和教师选择下一次训练重点。', 'Course cases are complete. Review feedback and choose the next practice focus with your instructor.') : t('阅读知识卡 → 回应微练习 → 完整案例 → 反思与反馈。', 'Read a card → complete a micro-practice → try a full case → reflect and review.'))
  }
  const renderAttempt = (attempt: Row, row: Row) => {
    const unlocked = role === 'instructor' || (!!attempt.self_reflection?.trim() && attempt.self_reflection_current !== false) || reflectionUnlocked[attempt.id]
    const goals = row.course?.learning_objectives || row.assignment.skill_tags?.map((id: string) => ({id, description: id})) || []
    return <article className="learning-attempt" key={attempt.id}><div className="learning-heading"><h4>{scenarios.find(item => item.scenario_id === attempt.scenario_id)?.scenario_brief || t('案例练习', 'Case practice')}</h4><a href={attempt.practice_href}>{t('打开练习对话', 'Open dialogue')}</a></div><p>{statusLabel(attempt.status, locale)} · {attempt.review?.status ? statusLabel(attempt.review.status, locale) : t('尚无复盘', 'No debrief yet')}</p>
      {role === 'human_therapist' && <section className="learning-reflection"><label>{t('看反馈之前，先回想一下', 'Reflect before reading feedback')}<textarea aria-label={t('看反馈之前，先回想一下', 'Reflect before reading feedback')} value={reflections[attempt.id] ?? attempt.self_reflection ?? ''} maxLength={2000} onChange={event => setReflections(current => ({...current, [attempt.id]: event.target.value}))} placeholder={t('我想表达什么？哪句话最不确定？下一次会怎么改？', 'What was I trying to convey? What felt uncertain? What would I change?')} /></label><div className="button-row"><button disabled={busy || !(reflections[attempt.id] ?? attempt.self_reflection ?? '').trim()} onClick={() => void saveReflection(attempt)}>{t('保存反思并查看反馈', 'Save reflection and view feedback')}</button><button disabled={busy} onClick={() => setReflectionUnlocked(current => ({...current, [attempt.id]: true}))}>{t('这次跳过反思，查看反馈', 'Skip reflection this time')}</button></div></section>}
      {attempt.self_reflection && attempt.self_reflection_current === false && <p className="hint-note">{t('对话更新前的反思已保留，可修改后重新保存。', 'Your reflection predates the latest dialogue. Update it and save again.')}</p>}{role === 'instructor' && attempt.self_reflection && <blockquote><strong>{t('学员反思', 'Learner reflection')}</strong><p>{attempt.self_reflection}</p></blockquote>}
      {unlocked && <><div className="button-row"><button disabled={busy || pendingJob(jobs['attempt:' + attempt.id] || {}) || attempt.status !== 'completed'} onClick={() => void runJudge('attempt', attempt.id)}>{t('获取目标行为反馈', 'Assess target behaviours')}</button>{role === 'instructor' && <button disabled={busy} onClick={() => chooseReview('attempt:' + attempt.id)}>{t('教师评价', 'Instructor review')}</button>}</div>{judgeView('attempt:' + attempt.id, goals)}{attempt.human_review && <>{!attempt.human_review_current && <p className="warning-note">{t('对话已变化，以下是旧版本的教师评价。', 'The dialogue has changed. This instructor review refers to an earlier version.')}</p>}{humanFeedback(attempt.human_review)}</>}{attempt.review?.summary && <details><summary>{t('完整复盘记录', 'Full debrief record')}</summary><pre>{JSON.stringify(attempt.review.summary, null, 2)}</pre></details>}</>}
      {role === 'instructor' && openReview === 'attempt:' + attempt.id && <section className="learning-review-form"><h4>{t('记录本次观察', 'Record your observations')}</h4><label>{t('复核人', 'Reviewer')}<input value={reviewer} onChange={e => setReviewer(e.target.value)} /></label><label>{t('完成方式', 'Performance context')}<select aria-label={t('完成方式', 'Performance context')} value={performanceLevel} onChange={e => setPerformanceLevel(e.target.value)}><option value="guided">{t('使用了指导或提示', 'With guidance or hints')}</option><option value="independent">{t('独立完成', 'Independently completed')}</option></select></label><label>{t('不同情境中的应用（可选）', 'Application in a different context (optional)')}<input value={transferContext} maxLength={500} onChange={e => setTransferContext(e.target.value)} /></label><label className="checkbox-line"><input type="checkbox" checked={safetyIssue} onChange={e => setSafetyIssue(e.target.checked)} />{t('需要督导处理的安全问题', 'Safety issue requiring supervision')}</label>{goals.map((objective: Row) => <section className="review-objective" key={objective.id}><label>{objective.description}<select value={ratings[objective.id] || ''} onChange={e => setRatings(current => ({...current, [objective.id]: Number(e.target.value)}))}><option value="">{t('选择目标评分', 'Choose an objective rating')}</option>{[1, 2, 3, 4, 5].map(value => <option key={value} value={value}>{value}/5</option>)}</select></label>{objective.rubric?.length > 0 && <details><summary>{t('评分描述', 'Rating anchors')}</summary>{objective.rubric.map((anchor: Row, i: number) => <p key={i}>{anchor.label || anchor.level}: {anchor.description}</p>)}</details>}{(objective.observable_behaviors || []).map((behavior: string) => {const current = (behaviorObservations[objective.id] || []).find(item => item.behavior === behavior) || {}; return <fieldset className="behavior-observation" key={behavior}><legend>{behavior}</legend><label>{t('观察状态', 'Observation status')}<select value={current.status || ''} onChange={e => updateBehavior(objective.id, behavior, {status: e.target.value, score: undefined})}><option value="">{t('请选择', 'Choose')}</option>{['observed', 'not_observed', 'not_applicable'].map(status => <option value={status} key={status}>{label(status)}</option>)}</select></label><label>{t('具体对话或建议', 'Dialogue evidence or suggestion')}<textarea maxLength={2000} value={current.note || ''} onChange={e => updateBehavior(objective.id, behavior, {note: e.target.value})} /></label></fieldset>})}</section>)}{row.course?.knowledge_references?.length > 0 && <details><summary>{t('标记本次参考的知识', 'Mark references used')}</summary>{row.course.knowledge_references.map((item: Row) => <label className="checkbox-line" key={item.unit_id}><input type="checkbox" checked={reviewEvidence.includes(item.unit_id)} onChange={e => setReviewEvidence(current => e.target.checked ? [...current, item.unit_id] : current.filter(id => id !== item.unit_id))} />{item.label || item.unit_id}</label>)}</details>}<label>{t('反馈与下一步建议', 'Feedback and next step')}<textarea value={comment} onChange={e => setComment(e.target.value)} /></label><div className="button-row"><button disabled={busy || !reviewer.trim() || !comment.trim() || !attempt.machine_passed || safetyIssue || goals.some((goal: Row) => !ratings[goal.id])} onClick={() => void submitReview(attempt, 'approved')}>{t('认可本次练习', 'Approve this attempt')}</button><button disabled={busy || !reviewer.trim() || !comment.trim()} onClick={() => void submitReview(attempt, 'needs_practice')}>{t('记录继续练习建议', 'Record further practice')}</button></div></section>}
    </article>
  }
  const renderMicro = (row: Row) => {
    const assignmentId = row.assignment.assignment_id; const data = micro[assignmentId]; const exercises = data?.exercises || row.course?.learning_units?.micro_practices || []
    return exercises.length > 0 && <section className="learning-micro-list"><h3>{t('先练一小步', 'Practise one small step')}</h3><p>{t('每次聚焦一个行为。提交的回应会单独保存，并可获得 AI 与教师反馈。', 'Focus on one behaviour at a time. Your response is saved for AI and instructor feedback.')}</p>{exercises.map((exercise: Row) => {const key = assignmentId + ':' + exercise.practice_id; const answer = answerFor(key); const submissions = (data?.submissions || []).filter((item: Row) => item.practice_id === exercise.practice_id); return <article className="learning-exercise" key={key}><h4>{exercise.title}</h4>{exercise.scenario_text && <blockquote className="learning-scenario"><strong>{t('来访者情境', 'Client situation')}</strong><p>{exercise.scenario_text}</p></blockquote>}<p>{exercise.prompt}</p><p className="hint-note">{t('练习行为', 'Target behaviour')}: {exercise.target_behavior}</p>{role === 'human_therapist' && <><label>{t('你的回应', 'Your response')}<textarea aria-label={t('你的回应', 'Your response')} value={answer.response_text} onChange={e => setAnswer(key, {response_text: e.target.value})} placeholder={t('写出你会对来访者说的话。', 'Write what you would say to the client.')} /></label><details onToggle={e => {if (e.currentTarget.open && !answer.hint_used) setAnswer(key, {hint_used: true})}}><summary>{t('需要一点提示', 'Show a hint')}</summary><p>{exercise.hint}</p></details>{answer.hint_used && <small>{t('本次已使用提示，会随回应记录。', 'Hint use will be recorded with this response.')}</small>}<label>{exercise.reflection_prompt || t('提交之前，想想你的选择', 'Reflect on your choice before submitting')}<textarea aria-label={exercise.reflection_prompt || t('提交之前，想想你的选择', 'Reflect on your choice before submitting')} value={answer.self_reflection} maxLength={2000} onChange={e => setAnswer(key, {self_reflection: e.target.value})} /></label><label className="checkbox-line"><input type="checkbox" checked={answer.skipReflection} onChange={e => setAnswer(key, {skipReflection: e.target.checked})} />{t('这次跳过自我反思', 'Skip self-reflection this time')}</label><button className="primary" disabled={busy || !answer.response_text.trim() || (!answer.self_reflection.trim() && !answer.skipReflection)} onClick={() => void submitMicro(assignmentId, exercise)}>{t('提交微练习', 'Submit micro-practice')}</button></>}{submissions.length > 0 && exercise.example_response && <details><summary>{t('查看示范回应与讨论', 'View a worked example and discussion')}</summary><p className="readable-output">{exercise.example_response}</p><p>{exercise.example_discussion}</p></details>}{submissions.map((submission: Row) => <article className="learning-submission" key={submission.submission_id}><div className="learning-heading"><h4>{t('已提交的回应', 'Submitted response')}</h4><small>{new Date(submission.created_at).toLocaleString(locale === 'zh' ? 'zh-CN' : 'en-US')}</small></div>{submission.exercise_current === false && <p className="warning-note">{t('这是课程修改前的练习回应，以下反馈保留原题版本。', 'This response belongs to an earlier version of the exercise.')}</p>}{submission.exercise_current === false && submission.exercise_snapshot && <details><summary>{t('查看提交时的题目', 'View the submitted exercise version')}</summary><blockquote><p>{submission.exercise_snapshot.scenario_text}</p><p>{submission.exercise_snapshot.prompt}</p></blockquote></details>}<p className="readable-output">{submission.response_text}</p>{submission.self_reflection && <p><strong>{t('自我反思：', 'Reflection: ')}</strong>{submission.self_reflection}</p>}<small>{submission.hint_used ? t('使用了提示', 'Hint used') : t('未使用提示', 'No hint used')}</small><div className="button-row"><button disabled={busy || pendingJob(jobs['submission:' + submission.submission_id] || {})} onClick={() => void runJudge('submission', submission.submission_id)}>{t('获取练习反馈', 'Get practice feedback')}</button>{role === 'instructor' && <button onClick={() => chooseReview('submission:' + submission.submission_id)}>{t('教师评价', 'Instructor review')}</button>}</div>{judgeView('submission:' + submission.submission_id, row.course?.learning_objectives || [])}{(submission.human_reviews || []).map((review: Row) => <div key={review.review_id}>{humanFeedback(review)}</div>)}{role === 'instructor' && openReview === 'submission:' + submission.submission_id && <section className="learning-review-form"><label>{t('复核人', 'Reviewer')}<input value={reviewer} onChange={e => setReviewer(e.target.value)} /></label><label>{t('评分（可选）', 'Rating (optional)')}<select aria-label={t('评分（可选）', 'Rating (optional)')} value={microScore} onChange={e => setMicroScore(e.target.value)}><option value="">{t('不评分', 'No rating')}</option>{[1, 2, 3, 4, 5].map(value => <option key={value} value={value}>{value}/5</option>)}</select></label><label>{t('具体反馈与下一步', 'Specific feedback and next step')}<textarea value={comment} onChange={e => setComment(e.target.value)} /></label><div className="button-row">{['approved', 'needs_practice'].map(decision => <button key={decision} disabled={busy || !reviewer.trim() || !comment.trim()} onClick={() => void act(async () => {await call('/learning/submissions/' + submission.submission_id + '/review', {decision, reviewer, comment, ...(microScore ? {score: Number(microScore)} : {})}); resetReview(); await refresh()})}>{label(decision)}</button>)}</div></section>}</article>)}</article>})}</section>
  }
  return <div className="workspace-page learning-studio">
    <button className="back-button" onClick={onBack}>← {t('返回工作台', 'Back to workbench')}</button>
    <header className="learning-hero"><div><p className="eyebrow">{t('心理咨询技能训练', 'Psychotherapy skills training')}</p><h1>{t('从理解，到练习，再到应用', 'Understand. Practise. Apply.')}</h1><p>{t('用知识卡理解一个技能，用短练习尝试，再放进完整案例中。', 'Understand a skill with a knowledge card, try a short exercise, then apply it in a full case.')}</p></div><label>{t('当前视角', 'Your view')}<select aria-label={t('当前视角', 'Your view')} value={role} onChange={e => setRole(e.target.value as 'instructor' | 'human_therapist')}><option value="instructor">{t('教师', 'Instructor')}</option><option value="human_therapist">{t('学员', 'Learner')}</option></select></label></header>
    <div className="learning-toolbar"><label>{role === 'instructor' ? t('学员标签（留空查看全部）', 'Learner label (blank for all)') : t('你的学员标签', 'Your learner label')}<input value={assignee} onChange={e => setAssignee(e.target.value)} placeholder={t('例如：学习小组 A', 'e.g. Study group A')} /></label><button disabled={busy || (role !== 'instructor' && !assignee.trim())} onClick={() => void act(refresh)}>{t('加载进展', 'Load progress')}</button><small>{t('使用教师分配课程时填写的同一标签。', 'Use the same label your instructor used for the assignment.')}</small></div>
    <nav className="learning-tabs" aria-label={t('课程导航', 'Course navigation')}>{(role === 'instructor' ? ['design', 'practice', 'progress'] : ['practice', 'progress']).map(value => <button key={value} aria-current={tab === value ? 'page' : undefined} className={tab === value ? 'active' : ''} onClick={() => setTab(value as typeof tab)}>{value === 'design' ? t('设计与分配', 'Design & assign') : value === 'practice' ? t('学习与练习', 'Learn & practise') : t('观察与进展', 'Observations & progress')}</button>)}</nav>
    {error && <p className="error-box" role="alert">{error}</p>}{notice && <p className="learning-notice" role="status">{notice}</p>}
    {Object.entries(microErrors).map(([id, failure]) => <section key={id} className="error-box learning-load-error" role="alert"><strong>{failure.title}</strong><p>{failure.message}</p>{micro[id] && <p>{t('已保留上次加载的回应与反馈，可能尚未包含最新记录。', 'Previously loaded responses and feedback are retained; recent changes may be missing.')}</p>}<button disabled={busy} onClick={() => void retryMicro(id)} aria-label={t('重试加载：', 'Retry loading: ') + failure.title}>{t('重试此任务', 'Retry this assignment')}</button></section>)}
    {role === 'instructor' && tab === 'design' && <>
      <section className="panel learning-agent-panel" aria-label={t('课程设计 Agent', 'Course design Agent')}>
        <div className="learning-heading"><div><p className="eyebrow">{t('协作式课程设计', 'COLLABORATIVE COURSE DESIGN')}</p><h2>{t('和课程 Agent 一起完成', 'Work with the course Agent')}</h2></div><span>{t('先对话，再执行', 'Talk first, execute second')}</span></div>
        <p>{t('像和同事讨论一样描述你的教学目标。Agent 会追问缺失信息、展示工具计划，并在你确认后调用知识检索、课程蓝图和情景生成。', 'Describe your teaching goal as you would to a colleague. The Agent asks only for missing decisions, shows its tool plan, and calls retrieval, course planning and scenario generation after you confirm.')}</p>
        <div className="learning-agent-thread" aria-live="polite">{agentMessages.map((item, index) => <div className={'learning-agent-message ' + item.role} key={index}><span>{item.role === 'assistant' ? 'Agent' : t('你', 'You')}</span><p>{item.text}</p></div>)}</div>
        <form className="learning-agent-composer" onSubmit={event => {event.preventDefault(); void sendCourseAgent()}}><textarea aria-label={t('告诉课程 Agent 你的想法', 'Tell the course Agent what you want')} value={agentInput} onChange={event => setAgentInput(event.target.value)} placeholder={t('例如：我想让初学者练习情绪验证，做 3 个低风险案例。', 'For example: I want beginners to practise validation in 3 low-risk cases.')} rows={3} disabled={agentBusy} /><div className="button-row"><button className="primary" type="submit" disabled={agentBusy || !agentInput.trim()}>{agentBusy ? t('Agent 思考中…', 'Agent is thinking…') : t('发送给 Agent', 'Send to Agent')}</button>{agentMessages.length > 1 && <button type="button" onClick={() => {setAgentMessages([initialAgentMessage(locale)]); setAgentPlan({}); setAgentAction('')}}>{t('重新开始讨论', 'Start over')}</button>}</div></form>
        {agentAction === 'confirm_blueprint' && <div className="learning-agent-plan" role="status"><strong>{t('下一步由你确认', 'Your confirmation is the next step')}</strong><p>{t('Agent 已整理出可见计划。确认后才会检索知识并生成可编辑课程草案。', 'The Agent has prepared a visible plan. Confirm to retrieve knowledge and create an editable course draft.')}</p><dl><div><dt>{t('主题', 'Topic')}</dt><dd>{agentPlan.title || agentPlan.description}</dd></div><div><dt>{t('案例数量', 'Cases')}</dt><dd>{agentPlan.scenario_count || starterCount}</dd></div><div><dt>{t('难度 / 风险', 'Difficulty / risk')}</dt><dd>{agentPlan.difficulty_band || difficultyBand} / {agentPlan.risk_band || riskBand}</dd></div></dl><button className="primary" disabled={busy} onClick={() => void buildBlueprintFromAgent()}>{t('确认并生成课程草案', 'Confirm and create course draft')}</button></div>}
      </section>
      <details className="learning-advanced-design" open={advancedOpen} onToggle={event => setAdvancedOpen(event.currentTarget.open)}><summary>{t('高级编辑：直接调整模板、目标、知识卡和微练习', 'Advanced editing: templates, objectives, cards and micro-practices')}</summary>
      <section className="panel learning-template"><div className="learning-heading"><h2>{t('教学起点', 'Teaching starting point')}</h2><small>{t('所有内容仍可修改', 'Every part is editable')}</small></div><p>{t('模板包含能力目标、行为标准、知识卡和微练习。已有草稿会自动保存；重新创建模板会替换当前编辑内容。', 'Templates include objectives, observable behaviours, knowledge cards, and micro-practices. Drafts save automatically; creating another starter replaces the current draft.')}</p><div className="button-row"><label>{t('教学模板', 'Teaching template')}<select aria-label={t('教学模板', 'Teaching template')} value={starterTemplate} onChange={e => {setStarterTemplate(e.target.value); setRiskBand(e.target.value === 'risk_and_safety_basics' ? 'elevated' : 'low')}}><option value="foundation_first_session">{t('首次会谈基础', 'First-session foundations')}</option><option value="risk_and_safety_basics">{t('风险识别与安全沟通', 'Risk and safety communication')}</option><option value="integrated_case_formulation">{t('从评估到工作假设', 'Assessment to working formulation')}</option></select></label><label>{t('生成案例数量', 'Cases to generate')}<select aria-label={t('生成案例数量', 'Cases to generate')} value={starterCount} onChange={e => setStarterCount(Number(e.target.value))}>{[1, 2, 3, 4, 5, 6].map(value => <option key={value} value={value}>{value}</option>)}</select></label><label>{t('沟通难度', 'Communication difficulty')}<select aria-label={t('沟通难度', 'Communication difficulty')} value={difficultyBand} onChange={e => setDifficultyBand(e.target.value)}><option value="low">{t('基础', 'Foundational')}</option><option value="medium">{t('中等', 'Intermediate')}</option><option value="high">{t('进阶', 'Advanced')}</option></select></label><label>{t('情境风险', 'Scenario risk')}<select aria-label={t('情境风险', 'Scenario risk')} value={riskBand} onChange={e => setRiskBand(e.target.value)}><option value="low">{t('低风险', 'Low')}</option><option value="elevated">{t('需关注', 'Elevated')}</option><option value="high">{t('高风险', 'High')}</option></select></label><button className="primary" aria-label={t('创建课程起点', 'Create course starter')} disabled={busy} onClick={() => void buildBlueprint()}>{t('直接创建课程草案', 'Create course draft directly')}</button></div></section>
      {(draft.objectives.length > 0 || draft.title) && <section className="panel learning-course-editor"><div className="learning-heading"><h2>{t('2. 调整教学内容', '2. Shape the learning content')}</h2><small>{t('草稿自动保存在此浏览器', 'Draft saves in this browser')}</small></div><label>{t('课程标题', 'Course title')}<input value={draft.title} onChange={e => patchDraft({title: e.target.value})} /></label><label>{t('课程说明', 'Course description')}<textarea aria-label={t('课程说明', 'Course description')} value={draft.description} onChange={e => patchDraft({description: e.target.value})} /></label>
        <h3>{t('目标与可观察行为', 'Objectives and observable behaviours')}</h3>{draft.objectives.map((goal, index) => <article className="learning-objective-editor" key={goal.id}><label>{t('希望学员做到什么', 'What should the learner be able to do?')}<textarea aria-label={t('希望学员做到什么', 'What should the learner be able to do?')} value={goal.description} onChange={e => patchGoal(index, {description: e.target.value})} /></label><label>{t('如何从对话中看出来（每行一个，最多 8 个行为）', 'Observable behaviours: one per line, up to 8')}<textarea aria-label={t('可观察行为', 'Observable behaviours')} value={(goal.observable_behaviors || []).join('\n')} onChange={e => patchGoal(index, {observable_behaviors: e.target.value.split('\n')})} /></label><details><summary>{t('编辑评分描述', 'Edit rating anchors')}</summary>{(goal.rubric || []).map((anchor: Row, anchorIndex: number) => <div className="learning-rubric-row" key={anchorIndex}><label>{t('等级名称', 'Level label')}<input value={anchor.label || ''} onChange={e => patchGoal(index, {rubric: goal.rubric.map((item: Row, i: number) => i === anchorIndex ? {...item, label: e.target.value} : item)})} /></label><label>{t('表现描述', 'Observed performance')}<textarea value={anchor.description || ''} onChange={e => patchGoal(index, {rubric: goal.rubric.map((item: Row, i: number) => i === anchorIndex ? {...item, description: e.target.value} : item)})} /></label></div>)}<button onClick={() => patchGoal(index, {rubric: [...(goal.rubric || []), {level: 'anchor_' + newId(), label: '', description: ''}]})}>{t('增加评分描述', 'Add rating anchor')}</button></details><button className="learning-remove" onClick={() => setDraft(current => ({...current, objectives: current.objectives.filter(item => item.id !== goal.id), knowledge_cards: current.knowledge_cards.filter(item => item.competency_id !== goal.id), micro_practices: current.micro_practices.filter(item => item.competency_id !== goal.id)}))}>{t('移除此目标及配套练习', 'Remove objective and related exercises')}</button></article>)}<button disabled={draft.objectives.length >= 12} onClick={() => patchDraft({objectives: [...draft.objectives, {id: 'objective_' + newId(), description: '', observable_behaviors: [], rubric: [], observation_statuses: ['observed', 'not_observed', 'not_applicable']}]})}>{t('增加学习目标', 'Add a learning objective')}</button>
        <details className="learning-unit-editor" open><summary>{t('知识卡：先理解，再行动', 'Knowledge cards: understand before acting')}</summary>{draft.knowledge_cards.map((card, index) => <article key={card.card_id}><label>{t('卡片标题', 'Card title')}<input value={card.title} onChange={e => patchUnit('knowledge_cards', index, {title: e.target.value})} /></label>{[['why_it_matters', t('为什么练习这个技能', 'Why practise this skill?')], ['when_to_use', t('什么情况下使用', 'When to use it')], ['common_misuse', t('容易出现的误用', 'Common misuse')]].map(([field, caption]) => <label key={field}>{caption}<textarea aria-label={caption} value={card[field] || ''} onChange={e => patchUnit('knowledge_cards', index, {[field]: e.target.value})} /></label>)}</article>)}</details>
        <details className="learning-unit-editor"><summary>{t('微练习：聚焦一个行为', 'Micro-practices: focus on one behaviour')}</summary>{draft.micro_practices.map((exercise, index) => <article key={exercise.practice_id}><label>{t('练习标题', 'Exercise title')}<input value={exercise.title} onChange={e => patchUnit('micro_practices', index, {title: e.target.value})} /></label><label>{t('本次要练的行为', 'Target behaviour')}<select aria-label={t('本次要练的行为', 'Target behaviour')} value={exercise.target_behavior || ''} onChange={e => patchUnit('micro_practices', index, {target_behavior: e.target.value})}>{(draft.objectives.find(goal => goal.id === exercise.competency_id)?.observable_behaviors || []).filter(Boolean).map((behavior: string) => <option key={behavior} value={behavior}>{behavior}</option>)}</select></label>{[['scenario_text', t('来访者情境或对话', 'Client situation or dialogue')], ['prompt', t('给学员的任务', 'Learner task')], ['hint', t('可选提示', 'Optional hint')], ['reflection_prompt', t('自我反思问题', 'Reflection question')], ['example_response', t('提交后可看的示范回应', 'Worked example shown after submission')], ['example_discussion', t('示范的思路与讨论', 'Example discussion')]].map(([field, caption]) => <label key={field}>{caption}<textarea aria-label={caption} value={exercise[field] || ''} onChange={e => patchUnit('micro_practices', index, {[field]: e.target.value})} /></label>)}</article>)}</details>
        <details><summary>{t('查看知识依据', 'View knowledge references')}</summary><p>{draft.blueprint?.knowledge_references?.length ? t('引用保持来源原文。教学解释和练习内容可在上方编辑。', 'References preserve the source text. Edit teaching explanations and exercises above.') : t('当前没有检索到适用依据，草案使用内置教学内容。', 'No applicable references were retrieved; this draft uses built-in teaching content.')}</p>{sourceList(draft.blueprint?.knowledge_references || [])}</details>
        <h3>{t('3. 选择案例，或生成新病例', '3. Select cases or generate new ones')}</h3><p>{t('已有审核案例可以直接加入课程。生成新病例时，会带上当前编辑的目标与教学内容，草稿也会保留。', 'Add approved cases directly. New case generation uses your current objectives and learning content, while preserving this draft.')}</p><div className="scenario-checklist">{scenarios.map(scenario => <label className="checkbox-line" key={scenario.scenario_id}><input type="checkbox" checked={draft.selected.includes(scenario.scenario_id)} onChange={e => patchDraft({selected: e.target.checked ? [...draft.selected, scenario.scenario_id] : draft.selected.filter(id => id !== scenario.scenario_id)})} /><span>{scenario.scenario_brief || scenario.scenario_id}</span></label>)}</div><div className="button-row"><button disabled={busy || !validDraft} onClick={() => void generateCases()}>{t('按当前目标生成病例草案', 'Generate cases from current objectives')}</button><button className="primary" disabled={busy || !validDraft || !draft.selected.length} onClick={() => void saveCourse()}>{t('保存课程', 'Save course')}</button></div>{!draft.selected.length && <p className="hint-note">{t('保存可分配课程前，选择至少一个已审核案例。', 'Select at least one approved case before saving an assignable course.')}</p>}
      </section>}
      </details>
      <section className="panel learning-assignment-editor"><h2>{t('4. 分配课程', '4. Assign a course')}</h2><label>{t('已保存的课程', 'Saved course')}<select aria-label={t('已保存的课程', 'Saved course')} value={courseId} onChange={e => {setCourseId(e.target.value); setAssignmentTitle(courses.find(item => item.course_id === e.target.value)?.title || '')}}><option value="">{t('选择课程', 'Choose a course')}</option>{courses.map(course => <option key={course.course_id} value={course.course_id}>{course.title}</option>)}</select></label>{courses.filter(course => course.course_id === courseId).map(course => <div key={course.course_id}><p>{course.description}</p><ul>{course.learning_objectives?.map((goal: Row) => <li key={goal.id}>{goal.description}</li>)}</ul><p>{course.scenario_ids.length} {t('个案例', 'cases')} · {course.learning_units?.micro_practices?.length || 0} {t('个微练习', 'micro-practices')}</p></div>)}<div className="learning-two-col"><label>{t('任务标题', 'Assignment title')}<input value={assignmentTitle} onChange={e => setAssignmentTitle(e.target.value)} /></label><label>{t('分配给学员标签', 'Assign to learner label')}<input value={assignee} onChange={e => setAssignee(e.target.value)} /></label></div><button className="primary" disabled={busy || !courseId || !assignmentTitle.trim() || !assignee.trim()} onClick={() => void act(async () => {const course = courses.find(item => item.course_id === courseId)!; await call('/assignments', {title: assignmentTitle, scenario_ids: course.scenario_ids, assignee: assignee.trim(), course_id: courseId, skill_tags: course.skill_tags, required_review_gate: course.completion_review_gate}); await refresh(); setTab('practice'); setNotice(t('课程已分配。学员用同一标签即可加载。', 'Course assigned. Learners can load it using the same label.'))})}>{t('分配任务', 'Assign practice')}</button></section>
    </>}
    {tab === 'practice' && <section className="learning-assignments">{!report?.assignments?.length && <div className="panel learning-empty"><h2>{t('从一份课程开始', 'Start with a course')}</h2><p>{role === 'instructor' ? t('先创建并分配课程，再在这里查看学员的练习与反馈。', 'Create and assign a course, then review practice and feedback here.') : t('输入教师提供的学员标签，再点击“加载进展”。', 'Enter the learner label provided by your instructor, then select Load progress.')}</p></div>}{report?.assignments?.map((row: Row) => <article className="panel learning-assignment" key={row.assignment.assignment_id}><div className="learning-heading"><div><p className="eyebrow">{row.assignment.assignee}</p><h2>{row.assignment.title}</h2></div><span>{row.completion.completed}/{row.completion.required} {t('个案例已完成', 'cases completed')}</span></div><p>{row.course?.description}</p><progress max={row.completion.required || 1} value={row.completion.completed} /><p className="learning-next"><strong>{t('下一步：', 'Next: ')}</strong>{nextStep(row)}</p>{(row.course?.learning_units?.knowledge_cards || []).length > 0 && <section><h3>{t('先读一张知识卡', 'Start with a knowledge card')}</h3><div className="learning-card-grid">{row.course.learning_units.knowledge_cards.map((card: Row) => <article className="learning-knowledge-card" key={card.card_id}><h4>{card.title}</h4><p>{card.why_it_matters}</p><strong>{t('何时使用', 'When to use')}</strong><p>{card.when_to_use}</p><strong>{t('留意误用', 'Common misuse')}</strong><p>{card.common_misuse}</p>{card.knowledge_unit_ids?.length > 0 && <details><summary>{t('知识来源', 'Knowledge sources')}</summary>{sourceList((row.course.knowledge_references || []).filter((item: Row) => card.knowledge_unit_ids.includes(item.unit_id)))}</details>}</article>)}</div></section>}{renderMicro(row)}<section><h3>{t('放进完整案例中练习', 'Apply the skill in a full case')}</h3><div className="learning-case-buttons">{row.assignment.scenario_ids.map((id: string) => <button key={id} disabled={busy} onClick={() => void startPractice(row.assignment, id)}><span>{row.completed_scenarios.includes(id) ? '✓ ' : ''}{scenarios.find(item => item.scenario_id === id)?.scenario_brief || id}</span><small>{t('打开练习 →', 'Start practice →')}</small></button>)}</div></section>{(row.attempts || []).map((attempt: Row) => renderAttempt(attempt, row))}<details><summary>{t('关联已有练习', 'Link existing practice')}</summary><label>{t('练习会话编号', 'Practice session ID')}<input value={links[row.assignment.assignment_id] || ''} onChange={e => setLinks(current => ({...current, [row.assignment.assignment_id]: e.target.value}))} /></label><button disabled={busy || !links[row.assignment.assignment_id]?.trim()} onClick={() => void act(async () => {await call('/assignments/' + row.assignment.assignment_id + '/attempts', {session_id: links[row.assignment.assignment_id]}); await refresh()})}>{t('关联记录', 'Link session')}</button></details></article>)}</section>}
    {tab === 'progress' && <section className="panel"><h2>{t('每项能力，积累了什么观察', 'What has been observed for each skill?')}</h2><p>{t('案例完成、教师评分、独立表现与不同情境中的应用分别展示。记录描述练习表现，帮助决定下一步。', 'Case completion, instructor ratings, independence, and application across contexts are shown separately to guide the next step.')}</p>{!report?.assignments?.length && <p>{t('加载学员课程后，这里会显示观察记录。', 'Load learner courses to see observations here.')}</p>}{report?.assignments?.map((row: Row) => <article className="learning-progress-group" key={row.assignment.assignment_id}><h3>{row.assignment.assignee} · {row.course?.title || row.assignment.title}</h3><div className="learning-card-grid">{row.pedagogical_progress?.competencies?.map((item: Row) => <article className="learning-knowledge-card" key={item.competency_id}><h4>{row.course?.learning_objectives?.find((goal: Row) => goal.id === item.competency_id)?.description || item.competency_id}</h4><p>{({not_started: t('尚无教师观察', 'No instructor observations yet'), orientation: t('初次观察', 'Initial observation'), guided: t('继续积累练习', 'Gathering practice observations'), independent: t('多次独立表现', 'Repeated independent performance'), transfer: t('观察到不同情境中的应用', 'Observed across different contexts'), blocked_safety: t('先与教师讨论安全问题', 'Discuss safety concerns with your instructor')} as Record<string, string>)[item.status] || item.status}</p><dl><div><dt>{t('观察次数', 'Observations')}</dt><dd>{item.attempt_count}</dd></div><div><dt>{t('独立表现', 'Independent')}</dt><dd>{item.independent_count}</dd></div><div><dt>{t('不同情境案例', 'Transfer cases')}</dt><dd>{item.transfer_case_count}</dd></div></dl></article>)}</div></article>)}<h3>{t('同一学员的评分记录', 'Ratings for the same learner')}</h3>{report?.trends?.map((trend: Row) => <article className="learning-trend" key={`${trend.assignee}:${trend.course_id}:${trend.objective_id}`}><strong>{trend.assignee} · {courses.find(course => course.course_id === trend.course_id)?.learning_objectives?.find((goal: Row) => goal.id === trend.objective_id)?.description || trend.objective_id}</strong><p>{t('观察数', 'Observations')}: {trend.count} · {t('最近评分', 'Latest rating')}: {trend.latest}/5 · {t('首末变化', 'First-to-latest change')}: {trend.change == null ? t('还需更多记录', 'More observations needed') : (trend.change > 0 ? '+' : '') + trend.change}</p><details><summary>{t('查看观察记录', 'View observations')}</summary><ol>{trend.observations.map((item: Row, index: number) => <li key={index}>{new Date(item.at).toLocaleDateString(locale === 'zh' ? 'zh-CN' : 'en-US')} · {item.value}/5 · {scenarios.find(scenario => scenario.scenario_id === item.scenario_id)?.scenario_brief || item.scenario_id}</li>)}</ol></details></article>)}</section>}
  </div>
}
